BOOK_N = {"Building Materials": 5, "Geo-technical": 10, "Engineering Mechanics": 1, "Strength of Materials": 2, "Structural Analysis": 6, "Reinforced Cement": 7, "Design of Steel": 8, "Building Construction": 0, "Construction Management": 9, "Estimating": 17, "Surveying": 14, "Fluid Mechanics": 3, "Hydraulic Machines": 4, "Irrigation": 13, "Engineering Hydrology": 12, "Environmental Engineering": 11, "Highway Engineering": 15, "Railway Engineering": 15, "Airport, Bridges": 15}

def lookup(book_unit, subtopic):
    """-> (subject number, [candidate chapter names with optional 'N:' subject prefix]) or ('other', None) / (None, None) if unknown"""
    for key, n in BOOK_N.items():
        if book_unit.startswith(key):
            if (key, subtopic) in YCT: return n, YCT[(key, subtopic)]
            if (key, "*") in YCT: return n, YCT[(key, "*")]
            return n, "unknown"
    return None, "unknown"
